templates.template:
.stormWelcome {display:flex;gap:2rem;align-items:center;padding:2rem;margin-bottom:2rem;border-radius:12px;background:fade(@xf-paletteColor2, 14%);}
.stormWelcome h1 {margin:0 0 .5rem;font-size:2rem;}
.stormWelcome .button {margin:.5rem .5rem 0 0;}
.stormArticle {position:relative;margin-left:12px;}
.stormArticle .block-header {font-size:15px;font-weight:normal;padding:8px 12px;}
.stormArticleDate {position:absolute;top:36px;left:-13px;width:38px;text-align:center;background:@xf-contentAltBg;border:1px solid @xf-borderColor;border-radius:4px;overflow:hidden;box-shadow:0 1px 3px fade(#000,10%);}
.stormArticleDate span {display:block;background:@xf-linkColor;color:@xf-contentBg;font-size:10px;font-weight:bold;text-transform:uppercase;padding:4px;}
.stormArticleDate strong {display:block;font-size:21px;padding:4px;}
.stormArticleByline {display:flex;justify-content:space-between;gap:10px;padding:8px 12px 8px 34px;color:@xf-textColorDimmed;font-size:11px;}
.stormArticleBody {display:flex;gap:20px;padding:4px 12px 14px 34px;align-items:flex-start;}
.stormArticleSnippet {flex:1;min-width:0;line-height:1.5;}
.stormArticleSnippet img {max-width:100%;height:auto;}
.stormArticleBody .avatar {flex-shrink:0;border:4px solid @xf-contentAltBg;box-shadow:0 0 0 1px @xf-borderColor;border-radius:50%;}
.stormArticleContinue {display:block;text-align:right;font-size:12px;font-weight:bold;}
.stormJoinAddress {display:flex;align-items:center;justify-content:space-between;gap:6px;}
.stormJoinAddress strong {font-size:18px;}
.stormJoin .button {font-size:11px;padding:5px 8px;}
.stormJoin p {margin:10px 0;font-size:12px;line-height:1.6;}
.stormJoinBadge {display:inline-block;padding:3px 7px;border-radius:20px;background:@xf-contentHighlightBg;color:@xf-textColor;font-size:11px;font-weight:bold;border:1px solid @xf-borderColor;}
.stormJoinBadge--online {border-color:@xf-linkColor;}
.stormJoin small {display:block;margin-top:6px;font-size:11px;}
@media(max-width:450px) {.stormArticleBody .avatar {display:none;} .stormArticleByline {flex-wrap:wrap;}}
@media(max-width:650px) {.stormWelcome {flex-direction:column;text-align:center;padding:1.5rem;} .stormWelcome h1 {font-size:1.6rem;}}
